<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/classifieds_v1370.php';$me=sk1370_require_login('/post-ad.php');$edit=(int)($_GET['edit']??0);$ad=$edit?sk1370_ad($edit,false):null;if($ad&&((int)$ad['user_id']!==sk1370_uid()&&!sk1370_admin())){http_response_code(403);exit('Forbidden');}$msg='';$err='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{sk1370_csrf_check();if($edit){sk1370_update_ad($edit,$_POST,$_FILES['images']??[]);$msg='Ad updated and sent for review.';$ad=sk1370_ad($edit,false);}else{$id=sk1370_create_ad($_POST,$_FILES['images']??[]);header('Location: /my-classifieds.php?created='.$id);exit;}}catch(Throwable $e){$err=$e->getMessage();}}$categories=sk1370_categories();$fields=$ad?sk1370_fields((int)$ad['category_id']):[];function sk1370_render_field_input_for_builder(array $f,string $v=''): string {$name='field_'.(int)$f['id'];$req=(int)$f['required']?' required':'';$type=(string)$f['field_type'];if($type==='select'){$opts=json_decode((string)$f['options_json'],true)?:[];$s='<select name="'.sk1370_h($name).'"'.$req.'><option value="">Select</option>';foreach($opts as $o)$s.='<option value="'.sk1370_h($o).'"'.($v===(string)$o?' selected':'').'>'.sk1370_h($o).'</option>';return $s.'</select>';}if($type==='number'||$type==='decimal')return '<input type="number" step="'.($type==='decimal'?'0.01':'1').'" name="'.sk1370_h($name).'" value="'.sk1370_h($v).'"'.$req.'>';return '<input name="'.sk1370_h($name).'" value="'.sk1370_h($v).'"'.$req.'>';}$vals=[];if($ad)foreach(sk1370_field_values((int)$ad['id']) as $v)$vals[$v['label']]=$v['value_text'];sk1370_shell($edit?'Edit Ad':'Post an Ad','post-ad');?><section class="post-wrap"><header><span class="eyebrow">SELL ON SHAHKOTPK</span><h1><?=$edit?'Edit your ad':'Post your ad'?></h1><p>Add accurate details and clear photos. Ads are reviewed before going live.</p></header><?php if($msg):?><div class="notice ok"><?=sk1370_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1370_h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="post-form" id="skc-post-form"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><div class="wizard-tabs"><button type="button" class="on" data-step="1">1 Category</button><button type="button" data-step="2">2 Details</button><button type="button" data-step="3">3 Photos</button><button type="button" data-step="4">4 Location & Contact</button></div><section data-wstep="1"><h2>Choose a category</h2><label>Category<select name="category_id" id="skc-category" required><option value="">Select category</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$ad&&(int)$ad['category_id']===(int)$c['id']?'selected':''?>><?=sk1370_h(($c['parent_id']?'— ':'').$c['name'])?></option><?php endforeach;?></select></label><div id="skc-category-fields" class="dynamic-fields"><?php foreach($fields as $f):?><label><?=sk1370_h($f['label'])?><?=sk1370_render_field_input_for_builder($f,$vals[$f['label']]??'')?></label><?php endforeach;?></div></section><section data-wstep="2" hidden><h2>Describe what you are offering</h2><label>Ad title<input name="title" maxlength="160" required value="<?=sk1370_h($ad['title']??'')?>" placeholder="e.g. Samsung Galaxy A54 8/256GB"></label><label>Description<textarea name="description" rows="8" maxlength="8000" required placeholder="Condition, features, reason for selling and useful details…"><?=sk1370_h($ad['description']??'')?></textarea></label><div class="three"><label>Price type<select name="price_type"><option value="fixed">Fixed price</option><option value="negotiable" <?=($ad['price_type']??'')==='negotiable'?'selected':''?>>Negotiable</option><option value="free" <?=($ad['price_type']??'')==='free'?'selected':''?>>Free</option><option value="contact" <?=($ad['price_type']??'')==='contact'?'selected':''?>>Contact for price</option></select></label><label>Price (PKR)<input type="number" min="0" step="1" name="price" value="<?=sk1370_h($ad['price']??'')?>"></label><label>Condition<select name="condition_code"><?php foreach(['new'=>'New','like_new'=>'Like new','used'=>'Used','refurbished'=>'Refurbished','not_applicable'=>'Not applicable'] as $k=>$v):?><option value="<?=$k?>" <?=($ad['condition_code']??'used')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div></section><section data-wstep="3" hidden><h2>Add photos</h2><p class="help">Up to <?=sk1370_h(sk1370_setting('classifieds_max_images','10'))?> JPG, PNG or WebP images. The first image becomes the cover.</p><?php if($ad):?><div class="edit-media"><?php foreach(sk1370_media((int)$ad['id']) as $m):?><img src="<?=sk1370_h($m['file_path'])?>" alt=""><?php endforeach;?></div><?php endif;?><label class="dropzone"><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple><b>Choose photos</b><span>Clear real photos help buyers understand the item.</span></label><div id="skc-preview" class="preview-grid"></div></section><section data-wstep="4" hidden><h2>Location & contact</h2><div class="two"><label>City<input value="Shahkot" disabled></label><label>Area / locality<input name="area" required value="<?=sk1370_h($ad['area']??'')?>" placeholder="e.g. Main Bazar, Circular Road"></label></div><label>Address hint <small>(public; avoid private home details)</small><input name="address_hint" value="<?=sk1370_h($ad['address_hint']??'')?>" placeholder="Nearby landmark or market"></label><div class="two"><label>Latitude <small>optional</small><input name="latitude" id="skc-lat" value="<?=sk1370_h($ad['latitude']??'')?>"></label><label>Longitude <small>optional</small><input name="longitude" id="skc-lng" value="<?=sk1370_h($ad['longitude']??'')?>"></label></div><button type="button" class="locate" id="skc-use-location">Use my current location</button><div class="two"><label>Contact preference<select name="contact_preference"><option value="chat">In-app chat only</option><option value="phone" <?=($ad['contact_preference']??'')==='phone'?'selected':''?>>Phone</option><option value="both" <?=($ad['contact_preference']??'')==='both'?'selected':''?>>Chat + phone</option></select></label><label>Phone <small>optional</small><input name="phone" inputmode="tel" value="<?=sk1370_h($ad['phone']??'')?>"></label></div><label class="check"><input type="checkbox" name="show_phone" value="1" <?=!empty($ad['show_phone'])?'checked':''?>> Allow phone number to be shown on the ad</label><div class="safety-note"><b>Marketplace safety</b><p>Meet in a public place, inspect items before payment, and keep conversations in ShahkotPK chat where possible. Restricted/unsafe goods are not allowed.</p></div></section><footer class="wizard-actions"><button type="button" class="prev" id="skc-prev" hidden>Back</button><button type="button" class="next" id="skc-next">Continue</button><button type="submit" class="publish" id="skc-submit" hidden><?=$edit?'Save Changes':'Submit Ad for Review'?></button></footer></form></section><?php sk1370_end();
